using Alpinarc.Api.Lodges;

namespace Alpinarc.Api.Stages;

/// <summary>
/// A hike from one lodge to another that can be done in one day. Directed: the way back is
/// a stage of its own, because its ascent, descent and hiking time differ. Shared by every
/// tour that uses it, so a correction applies to all of them.
/// </summary>
public sealed class Stage
{
    /// <summary>Generated by Postgres on insert.</summary>
    public Guid Id { get; init; }

    public Guid FromLodgeId { get; set; }

    public Lodge FromLodge { get; set; } = null!;

    public Guid ToLodgeId { get; set; }

    public Lodge ToLodge { get; set; } = null!;

    public int DistanceMeters { get; set; }

    public int AscentMeters { get; set; }

    public int DescentMeters { get; set; }

    /// <summary>The hiking time, as given on a signpost or in a hut guide.</summary>
    public int DurationMinutes { get; set; }

    /// <summary>Generated by Postgres on insert.</summary>
    public DateTimeOffset CreatedAt { get; init; }
}

/// <summary>
/// The allowed ranges for a stage's numbers. Used by both the request validation and the
/// database check constraints, so the two can't drift apart.
/// </summary>
public static class StageLimits
{
    public const int MinDistanceMeters = 1;

    /// <summary>100 km.</summary>
    public const int MaxDistanceMeters = 100_000;

    public const int MinElevationMeters = 0;

    /// <summary>For both ascent and descent.</summary>
    public const int MaxElevationMeters = 10_000;

    public const int MinDurationMinutes = 1;

    /// <summary>24 hours: a stage fits in one day.</summary>
    public const int MaxDurationMinutes = 24 * 60;
}
